'use strict';
// Isolated interaction prototype. No fetch, MCP, native helper, storage or AI.
const $=id=>document.getElementById(id);
const vendors={
  cloudflare:{name:'Cloudflare',url:'https://mcp.cloudflare.com/mcp',reference:'https://github.com/cloudflare/mcp',help:'Use Cloudflare’s official server and sign-in. CaptionKeep supplies the client connection, not a replacement DNS API.',tools:[['dns.create','Create TXT record'],['dns.read','Look up a DNS record']]},
  github:{name:'GitHub',url:'https://api.githubcopilot.com/mcp/',reference:'https://github.com/github/github-mcp-server/blob/main/docs/host-integration.md',help:'Use GitHub’s server. Remote OAuth requires a supported client/app registration; a login button alone cannot supply it.',tools:[['issue.create','Create an issue'],['issue.read','Look up an issue']]},
  notion:{name:'Notion',url:'https://mcp.notion.com/mcp',reference:'https://developers.notion.com/guides/mcp/get-started-with-mcp',help:'Use Notion’s hosted MCP and official authorization. Choose the intended workspace, not whichever login happens to be open.',tools:[['page.create','Create a decision note'],['page.read','Find a page']]},
  custom:{name:'Custom remote MCP',url:'https://mcp.example.com/mcp',help:'Bring an organization-approved endpoint. Real compatibility, authentication and policy need verification; this demo does not discover it.',tools:[['custom.demo','Run a synthetic example']]},
  local:{name:'Local MCP',url:'',help:'A local server needs the one-time helper and a reviewed installation. This demo does not launch commands or install anything.',tools:[['local.demo','Run a synthetic local example']]}
};
const scenarios={dns:{text:'Can we add a TXT record for the staging verification?',vendor:'cloudflare',title:'_verify.staging.example.com',value:'captionkeep-demo-verification'},issue:{text:'Let’s track the onboarding fix as an issue for Engineering.',vendor:'github',title:'Simplify MCP onboarding',value:'Provide vendor-led sign-in and multiple account connections.'},note:{text:'Capture that decision in our team workspace.',vendor:'notion',title:'Meeting decision — staging verification',value:'Use a temporary TXT record in staging after explicit approval.'}};
let connections,sequence,scenario='dns',proposal=null;
function tell(text){$('action-status').textContent=text;}
function invalidate(){proposal=null;$('confirm-target').checked=false;$('approve').disabled=true;}
function step(name){for(const s of ['choose','review','result']){$(s+'-panel').hidden=s!==name;const item=$('step-'+s);item.removeAttribute('aria-current');if(s===name)item.setAttribute('aria-current','step');}}
function populateConnections(preferred){const previous=preferred||$('connection').value;$('connection').replaceChildren();for(const c of connections){const option=document.createElement('option');option.value=c.id;option.textContent=c.label;$('connection').append(option);}if(connections.some(c=>c.id===previous))$('connection').value=previous;$('connection-count').textContent=String(connections.length);updateTools();}
function selectedConnection(){return connections.find(c=>c.id===$('connection').value);}
function updateTools(){invalidate();const c=selectedConnection();$('tool').replaceChildren();if(!c){$('review').disabled=true;$('connection-detail').textContent='Add a demo connection to continue.';return;}$('review').disabled=false;for(const [value,label] of vendors[c.vendor].tools){const option=document.createElement('option');option.value=value;option.textContent=label+' · simulated';$('tool').append(option);}$('connection-detail').textContent=c.label+' · '+c.environment+' · demo account only. '+(c.vendor==='local'?'Local stdio through helper.':'Remote HTTP through helper.');}
function chooseScenario(name){scenario=name;invalidate();step('choose');for(const button of document.querySelectorAll('[data-scenario]')){const selected=button.dataset.scenario===name;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));}const s=scenarios[name];$('selected-context').textContent='“'+s.text+'”';const preferred=connections.find(c=>c.vendor===s.vendor);populateConnections(preferred?.id);$('operation-title').value=s.title;$('operation-value').value=s.value;tell('Scripted proposal selected. No AI interpretation or operation has run.');}
function reset(){connections=[{id:'c1',vendor:'cloudflare',label:'Cloudflare — Staging',environment:'STAGING',endpoint:vendors.cloudflare.url},{id:'c2',vendor:'github',label:'GitHub — Engineering',environment:'ENGINEERING',endpoint:vendors.github.url},{id:'c3',vendor:'notion',label:'Notion — Team workspace',environment:'TEAM WORKSPACE',endpoint:vendors.notion.url}];sequence=3;chooseScenario('dns');tell('Select a sample request or open Connections to add another demo service.');}
for(const button of document.querySelectorAll('[data-scenario]'))button.addEventListener('click',()=>chooseScenario(button.dataset.scenario));
$('connection').addEventListener('change',()=>{updateTools();tell('Destination changed. Review the account and proposal again.');});
for(const id of ['tool','operation-title','operation-value'])$(id).addEventListener('input',invalidate);
$('review').addEventListener('click',()=>{const c=selectedConnection();if(!c)return;if(!$('operation-title').value.trim()){tell('Enter a record name or title before review.');$('operation-title').focus();return;}
  proposal={connectionId:c.id,connection:c.label,environment:c.environment,endpoint:c.endpoint||'Local synthetic server',tool:$('tool').value,arguments:{name:$('operation-title').value.trim(),details:$('operation-value').value},selectedContext:scenarios[scenario].text};
  $('review-summary').replaceChildren();for(const [label,value] of [['Service / account',proposal.connection],['Environment',proposal.environment],['Destination',proposal.endpoint],['Operation',proposal.tool]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;$('review-summary').append(dt,dd);}
  $('exact-operation').textContent=JSON.stringify({tool:proposal.tool,arguments:proposal.arguments},null,2);$('confirm-target').checked=false;$('approve').disabled=true;step('review');$('review-heading').focus();tell('Review the exact destination and arguments. This remains a simulation.');});
$('confirm-target').addEventListener('change',()=>{$('approve').disabled=!proposal||!$('confirm-target').checked;});
$('approve').addEventListener('click',()=>{if(!proposal||!$('confirm-target').checked)return;const sealed=proposal;invalidate();if(!connections.some(c=>c.id===sealed.connectionId)){step('choose');tell('The connection was removed. Choose a destination again.');return;}$('result-text').textContent='Demo operation '+sealed.tool+' returned a synthetic result for “'+sealed.arguments.name+'” on '+sealed.connection+'. No record, issue or page was actually created.';step('result');$('result-heading').focus();tell('Simulation complete. Nothing was sent to any service.');});
$('back').addEventListener('click',()=>{invalidate();step('choose');$('connection').focus();tell('Proposal returned for editing; previous approval is invalid.');});
$('another').addEventListener('click',()=>{chooseScenario(scenario);$('action-heading').focus();});
$('reset').addEventListener('click',reset);
function renderList(){$('connection-list').replaceChildren();for(const c of connections){const row=document.createElement('li'),description=document.createElement('div'),title=document.createElement('strong'),detail=document.createElement('small'),button=document.createElement('button');title.textContent=c.label;detail.textContent=vendors[c.vendor].name+' · '+c.environment+' · demo connected';description.append(title,detail);button.textContent='Remove';button.setAttribute('aria-label','Remove '+c.label);button.addEventListener('click',()=>{connections=connections.filter(x=>x.id!==c.id);invalidate();step('choose');populateConnections();renderList();$('connection-status').textContent='Removed this demo connection only. Other accounts are unchanged.';$('connections-heading').tabIndex=-1;$('connections-heading').focus();});row.append(description,button);$('connection-list').append(row);}}
function vendorChanged(){const v=vendors[$('vendor').value];$('vendor-help').textContent=v.help;$('account-label').value=v.name+' — '+($('vendor').value==='cloudflare'?'Production':'My workspace');$('endpoint').value=v.url;$('endpoint-field').hidden=$('vendor').value==='local';$('endpoint').required=$('vendor').value!=='local';$('vendor-reference').hidden=!v.reference;if(v.reference)$('vendor-reference').href=v.reference;$('add-connection').textContent=$('vendor').value==='local'?'Simulate local enrollment':'Simulate vendor authorization';$('connection-status').textContent='';}
$('vendor').addEventListener('change',vendorChanged);
$('endpoint').addEventListener('input',()=>{$('endpoint').setCustomValidity('');});
$('manage').addEventListener('click',()=>{renderList();vendorChanged();$('connections-dialog').showModal();});
$('close-connections').addEventListener('click',()=>{$('connections-dialog').close();$('manage').focus();});
$('connections-dialog').addEventListener('close',()=>{$('manage').focus();});
$('add-form').addEventListener('submit',event=>{event.preventDefault();const vendor=$('vendor').value,label=$('account-label').value.trim();if(!label){$('account-label').focus();return;}let endpoint='';if(vendor!=='local'){try{const url=new URL($('endpoint').value);if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash)throw Error('invalid');endpoint=url.href;}catch{$('endpoint').setCustomValidity('Use an HTTPS endpoint without credentials, query parameters or fragments.');$('endpoint').reportValidity();return;}}
  if(connections.some(c=>c.label===label)){ $('connection-status').textContent='Use a distinct account/environment label so you can tell these connections apart.';return;}
  const c={id:'c'+(++sequence),vendor,label,environment:label.toLowerCase().includes('production')?'PRODUCTION — CHECK CAREFULLY':'CUSTOM DEMO ACCOUNT',endpoint};connections.push(c);invalidate();step('choose');populateConnections(c.id);renderList();$('connection-status').textContent='Simulated authorization complete. Added '+label+' without replacing any existing connection. Close this panel to try its tools.';tell('New demo connection selected. Confirm the intended account before every operation.');});
reset();
